#include <vector>
#include <omp.h>

double productWithInverses(std::vector<double> const& x) {
    const std::size_t n = x.size();
    if (n == 0) return 1.0;

    // Compute in log-domain to avoid order-dependence from floating-point
    // multiplication (which can vary with thread scheduling).
    double sumLog = 0.0;

    #pragma omp parallel for reduction(+:sumLog)
    for (std::size_t i = 0; i < n; ++i) {
        const double v = x[i];
        // Assumes v != 0 and v > 0 for log; if inputs can be <=0, a different
        // approach (exact, deterministic multiplication tree) would be needed.
        const double lv = log(v);
        sumLog += ((i & 1u) == 0u) ? lv : -lv;
    }

    return exp(sumLog);
}
